"""Create Codex from current contracts and raw Chromium captures from matching receipts.
Plans are labeled diagrams. No image synthesis or retouching is performed."""
from pathlib import Path
import json,re,html,base64,hashlib
R=Path(__file__).resolve().parent.parent
J=lambda p:json.loads((R/p).read_text());e=lambda s:html.escape(str(s))
C=J('report/CONTRATS_LEVEL_DESIGN_V113.json');B=J('report/browser-results-v113.json');D=J('report/tactics-drive-v113.json')
assert all(t['ok'] for t in B['tests']) and not B['pageErrors'] and not B['consoleErrors']
assert B['htmlSha256']==hashlib.sha256((R/'JOUER_ALIENS_V113.html').read_bytes()).hexdigest()
node=int(re.search(r'# pass (\d+)',(R/'report/node-tests-v113.txt').read_text()).group(1))
STYLE='*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0a1219;color:#c9d7dd;font:16px/1.85 system-ui,Arial,sans-serif}main{max-width:1180px;margin:auto;padding:54px 32px 90px}a{color:#c3ddda}h1{font:400 clamp(42px,6vw,76px)/1.08 Georgia,serif;color:#e9e6d9;max-width:960px;margin:24px 0 28px}h2{font:400 30px/1.3 Georgia,serif;color:#d7e4e7;margin:40px 0 16px;border-top:1px solid #354d5d;padding-top:28px}h3{font-size:19px;color:#d5c6a3;font-weight:500}.kicker{font:11px/1.5 monospace;letter-spacing:.23em;color:#85a9bd;text-transform:uppercase}.lead{font-size:21px;max-width:930px;line-height:1.6}.callout{padding:19px 23px;border-left:3px solid #b49b64;background:#182933;color:#c6d9d9;margin:26px 0}.metrics{display:flex;flex-wrap:wrap;gap:14px}.metric{padding:16px 23px;border:1px solid #35505c;background:#12232e;min-width:158px}.metric strong{font:400 33px Georgia,serif;display:block;color:#d6c7a4}.metric small{font-size:12px;color:#92acb8}nav{display:flex;flex-wrap:wrap;gap:21px;margin:24px 0}table{border-collapse:collapse;width:100%;font-size:12px;line-height:1.55;margin:20px 0}th,td{padding:11px;border:1px solid #354b58;text-align:left;vertical-align:top}th{background:#1d3441}tr:nth-child(even){background:#13232d}.rooms{margin-top:28px}.room{border:1px solid #38566a;background:linear-gradient(130deg,#192e3a80,#101e2780);padding:26px;margin:26px 0}.room h2{border:0;padding:0;margin-top:0}.diagram{width:100%;height:auto;background:#101e26;border:1px solid #344e5f}.small{font:12px/1.7 monospace;color:#89a4b2;overflow-wrap:anywhere}figcaption{overflow-wrap:anywhere}figure{margin:30px 0}img{width:100%;height:auto;display:block;border:1px solid #496878}figcaption{font-size:13px;color:#9ab2bd;margin-top:10px}details{border:1px solid #3d5567;background:#11232d;padding:17px;margin:16px 0}summary{cursor:pointer;color:#c8dfe1}input{padding:15px;width:100%;background:#142937;color:#dde9e9;border:1px solid #6e92a1;font:15px system-ui}code,pre{font:12px/1.7 monospace;overflow-wrap:anywhere}pre{background:#0b1c26;padding:18px;white-space:pre-wrap}.hide{display:none}.chip{padding:4px 10px;border:1px solid #4c697b;font-size:11px;color:#b5cfd4}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:720px){main{padding:25px 16px}.room{padding:15px}h1{font-size:40px}.lead{font-size:18px}table{display:block;overflow-x:auto}.two{display:block}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;color:#222}h1,h2,h3{color:#222}nav,input{display:none}figure,.room{break-inside:avoid}main{padding:0}}'
def page(title,b,js=''):return f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><style>{STYLE}</style></head><body><main>{b}</main>{js}</body></html>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def metrics(rows):return '<div class="metrics">'+''.join(f'<div class="metric"><strong>{e(n)}</strong><small>{e(t)}</small></div>' for n,t in rows)+'</div>'
def diagram(r):
 out=[f'<svg class="diagram" viewBox="-25 -35 {r["width"]+50} {r["depth"]+90}" xmlns="http://www.w3.org/2000/svg" aria-label="Plan calculé du lieu, pas une capture"><rect x="0" y="0" width="{r["width"]}" height="{r["depth"]}" fill="#10252e" stroke="#608091"/>']
 for b in r['solids']:
  out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="{"#649faa" if b.get("material")=="glass" else "#516876"}" fill-opacity=".65" stroke="#9db2b8"/><text x="{b["x"]+3}" y="{b["z"]+14}" font-size="11" fill="#e3e1c7">{e(b["id"])}</text>')
 for b in r['doors']+r['hatches']:out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="#b2925655" stroke="#dabd7e"/>')
 for c in r['controls']:
  out.append(f'<circle cx="{c["x"]}" cy="{c["z"]}" r="8" fill="{"#b9dfde" if c["circuit"]=="service" else "#dab981"}"/><text x="{c["x"]+13}" y="{c["z"]+4}" font-size="12" fill="#e3e4ca">{e(c["id"])}</text>')
 for l in r['props']:
  if l['type']=='lamp':out.append(f'<rect x="{l["x"]-10}" y="{l["z"]-4}" width="20" height="8" fill="#d8d7a8"/>')
 for x in r['exits']:out.append(f'<circle cx="{x["x"]}" cy="{x["z"]}" r="14" fill="#172c39" stroke="#98d0c1"/><text x="{max(30,min(1170,x["x"]+15))}" y="{x["z"]-18}" fill="#a3cfc7" font-size="12">{e(x["label"])}</text>')
 return ''.join(out)+'</svg>'
old=(R/'CODEX_LEVEL_DESIGN_V112.md').read_text();rules=[]
for m in re.finditer(r'^### (\d+) — (.+)\n+([\s\S]*?)(?=\n##|\Z)',old,re.M):
 if int(m[1])<=48:rules.append((m[2],m[3].strip()))
assert len(rules)==48
rules[0]=('Un meilleur usage des lieux, pas une nouvelle checklist','V113 poursuit les dix lieux de V112 et les neuf pièces de l’opération, sans nouvelle salle, population ou objectif obligatoire. Les onze raccords et les cinq objectifs de repli restent conservés. Les ordres de position, secteurs et consignes de feu utilisent cette géométrie existante.')
rules[34]=('Reprendre la lumière et le placement sans reconstruire la partie','L’enveloppe V113 conserve les mondes, l’équipe, les ressources, les circuits, les balises, les ordres et leurs angles. Une V112 est d’abord validée par son importeur réel ; ses données restent identiques et les nouveaux registres tactiques sont vierges. Les états incohérents sont refusés avant remplacement et la reprise reste en pause.')
rules += [
 ('Désigner un poste dans le monde, pas une coordonnée décorative','X puis clic sélectionne un point au sol visible à moins de 520 unités de Ripley. Un poste doit être libre pour le gabarit de chaque équipier, avec une marge de sept unités autour des autres réservations. Les volumes des portes et des seuils restent interdits même lorsqu’ils sont ouverts. Une commande collective échoue entièrement si un membre ne dispose pas d’une destination accessible.'),
 ('Marcher jusqu’au poste sans téléportation de rattrapage','Chaque équipier rejoint réellement son appui avec le planificateur du monde. Les meubles, sas et équipiers restent des obstacles. Un trajet interrompu par une fermeture est recalculé après modification de la géométrie ; les tentatives sans route sont espacées pour éviter une boucle coûteuse. L’arrivée se fait à sept unités ou moins. Aucun spawn ni changement direct des coordonnées ne remplace le trajet.'),
 ('Engager une direction et garder ses angles morts','N puis clic engage un secteur de 100° depuis le poste ou l’appui actuel du Marine. Le curseur du joueur ne le redirige plus après validation. Le Marine rejoint d’abord son poste, puis surveille son angle. L’ordre Couvrir historique conserve son acquisition habituelle tant qu’aucun secteur explicite n’a été donné.'),
 ('Séparer position et discipline de feu','2 retient ou autorise le feu du ou des Marines sélectionnés sans déplacer leurs postes. Les états sont individuels. Retenir ne met ni les Xénos ni le reste du groupe en pause. G, H et C quittent les postes explicites ; le regroupement pour un transfert annule les réservations locales. La discipline de feu reste mémorisée indépendamment.'),
 ('Newt : une place sûre sans transformation en combattante','Newt recrutée peut recevoir un poste individuel ou accompagner les réservations du groupe. Sa route est physique comme celle des Marines. Aucun angle de tir ni état de feu ne peut lui être attribué ; son chargeur reste à zéro. Elle doit ensuite être rappelée et rejoindre le seuil pour quitter la pièce.'),
 ('Une tourelle fixe à orienter sur place','Sélectionner Sentinelle puis N exige Ripley à moins de 76 unités, à vue et sans obstacle de corps. L’affût tourne pendant 1,15 seconde ; l’angle final n’est attribué qu’au terme du geste. La tourelle ne tire pas pendant cette préparation. Marche, tir, blessure, éloignement ou changement de la cible interrompent la rotation. Ni munition, ni santé, ni déplacement de l’affût ne sont accordés.'),
 ('Ne pas tirer automatiquement à travers un allié vivant','Avant un tir automatique, chercher la première intersection de la trajectoire avec le monde et les contacts. Si une silhouette amie se trouve avant cette première collision, attendre ou choisir un autre contact admissible. Une silhouette située derrière la première cible n’annule pas ce tir. La marge autour de l’allié est de quatre unités. Ce verrou préventif ne change pas la visée ni les règles des tirs manuels du joueur.'),
 ('Conserver les autres raisons de ne pas tirer','Le secteur ne remplace pas la portée, le délai entre tirs, les munitions, le verre, les portes ni la perception dans le noir. La torche et les balises éclairent toujours les deux camps. Un ennemi caché, hors angle ou sans ligne libre ne devient pas une cible valide parce qu’un poste a été dessiné.'),
 ('Dessiner le plan de l’équipe sans ajouter un radar','Les chemins et appuis sont des annotations du sol partagé, pas des décors mobiles ni des marqueurs ennemis. Les arcs représentent les directions engagées, limités visuellement à 160 unités et découpés par la géométrie projectile. Ils ne représentent pas la portée totale de l’arme, qui garde sa règle de 440 pour un Marine et590 pour la sentinelle. Les indications d’échec restent hors terrain.'),
 ('La désignation ne suspend pas la menace','X et N activent un mode de clic distinct : le clic commande au lieu de tirer. Le temps continue. Échap, clic droit ou ouverture d’un panneau annule cette désignation ; une pause explicite seule suspend la simulation. Les contrôles et leur état sélectionné restent dans la bande d’ordres, hors canvas, y compris sur les viewports courts.'),
 ('Une sauvegarde stricte des postes et des rotations','Enveloppe113 : postes identifiés par membre, pièce, position, angle et arrivée ; registres de discipline ; angle/feu de la sentinelle et compteurs équilibrés. Les champs inattendus, Newt armée, postes dans les seuils, angles non finis ou bilans de rotations impossibles sont refusés avant mutation. La rotation en cours reprend au même avancement en pause. Les caches de chemins transitoires ne sont pas des données d’export.'),
 ('Recette d’un placement tactique jouable','Depuis l’insertion normale : donner des postes, enregistrer pendant la marche, revenir, orienter deux secteurs, retenir et autoriser séparément ; placer Newt ; réorienter l’affût à proximité avec reprise à mi-geste ; dégager l’axe de la sentinelle, tenir sans tirer manuellement et rejoindre le repli. Les états dirigés qui injectent une configuration pour tester une limite sont comptés séparément des parcours complets.')
]
assert len(rules)==60
body='<p class="kicker">ALIENS / V113 / Codex de conception</p><h1>Tenir les angles</h1><p class="lead">Désigner un appui, y arriver, puis garder son secteur. La ligne de défense existe dans le même monde que les balles et les alliés.</p>'+metrics([(60,'règles de conception'),(10,'lieux inspectables'),(11,'liaisons réciproques'),(0,'nouvel objectif imposé')])
body+='<nav><a href="JOUER_ALIENS_V113.html">Jouer</a><a href="RAPPORT_ILLUSTRE_V113.html">Rapport illustré</a><a href="#regles">Règles</a><a href="#lieux">Fiches de lieux</a></nav><div class="callout">Suite autonome V112, pas une fusion aux 64 salles natives de Tantalus. Les plans ci-dessous sont des schémas calculés depuis les données ; les captures réelles sont réservées au rapport illustré.</div>'
body+=table(['Commande','Condition','Effet'],[['X + clic','sol visible à moins de520','marche puis poste, seuils interdits'],['N + clic','Marine au même lieu','secteur fixé de100°, direction non asservie au curseur'],['2','Marine sélectionné ; sentinelle à portée','retenir / autoriser sans déplacer le poste'],['N — sentinelle','distance76 et ligne libre','rotation1,15s interruptible'],['G / H / C','commandes historiques','annulent les postes explicites sans donner de munitions']])
body+='<h2 id="regles">Contrats communs et V113</h2>';md=['# ALIENS V113 — Tenir les angles / Codex level design','Suite autonome V112. Soixante règles, dix fiches, aucun lieu/objectif/population nouveau.']
for n,(title,text) in enumerate(rules,1):
 body+=f'<details><summary>{n:02} — {e(title)}</summary><p>{e(text)}</p></details>';md += [f'### {n} — {title}',text]
body+='<h2 id="lieux">Dix lieux conservés</h2><label for="filter">Rechercher un lieu, un support ou un raccord</label><input id="filter" placeholder="Operations, sentinelle, optique…"><p class="small" id="filter-note">10 lieux affichés</p><div class="rooms">'
for r in C['rooms']:
 search=' '.join([r['title'],r['id'],r['goal'],json.dumps(r['props'],ensure_ascii=False),json.dumps(r['exits'],ensure_ascii=False)]).lower();lp=next(l for l in C['lightingProfiles'] if l['roomId']==r['id'])
 body+=f'<article class="room" data-search="{e(search)}"><p class="kicker">CATALOGUE HÉRITÉ / CONSERVÉ · {e(r["mode"])}</p><h2>{e(r["title"])}</h2><p>{e(r["goal"])}</p><p class="small">{e(r["id"])} · {r["width"]} × {r["depth"]} unités · {"opération et inspection" if r["connected"] else "inspection isolée"}</p>'
 body+='<figure>'+diagram(r)+'<figcaption>Plan calculé : solides gris, portes/sas ambre, commandes cyan, points de raccord. Les portes et seuils sont exclus des postes tactiques, même ouverts. Pas une capture du jeu.</figcaption></figure>'
 body+=table(['Raccord','Seuil local x,z','Arrivée locale x,z','Destination','État initial'],[[x['label'],f"{x['x']}, {x['z']}",f"{x['arrival']['x']}, {x['arrival']['z']}",x['to']['room'],'fermé' if next(l for l in C['links'] if l['id']==x['linkId']).get('initialOpen',True)==False else 'ouvert']for x in r['exits']])
 body+=f'<p>Service <code>{e(lp["controlId"])}</code> : {len(lp["lamps"])} lampes supportées. Les balises et la torche gardent leurs règles. Avant d’adopter un poste, tester le gabarit, le chemin puis la ligne de tir avec le groupe au complet.</p>'
 body+=table(['Prop','Type','Support','Position x,z','Élévation'],[[p['id'],p['type'],p.get('supportId')or p.get('support','support du catalogue'),f"{p['x']}, {p['z']}",p.get('elevation',0)] for p in r['props']])
 body+=table(['Volume','x,z','w,d','Hauteur','Matériau'],[[p['id'],f"{p['x']}, {p['z']}",f"{p['w']}, {p['d']}",p.get('h','—'),p.get('material','structure')] for p in r['solids']+r['doors']]);body+='</article>'
 md += [f'## {r["title"]}',f'{r["id"]} — {r["mode"]}. {r["goal"]}. Catalogue inchangé. Postes interdits dans les volumes de portes et seuils.','```json\n'+json.dumps({'exits':r['exits'],'solids':r['solids'],'doors':r['doors'],'controls':r['controls'],'props':r['props']},ensure_ascii=False,indent=2)+'\n```']
body+='</div><h2>Géométrie, niveaux de dessin et relecture</h2><p>Parallaxe lointaine uniquement ; les meubles, pieds des personnages, arcs tactiques et seuils sont projetés depuis le sol commun. Les routes servent au déplacement, pas à révéler une menace au-delà d’un mur. Les arcs sont des repères de commandement abrégés, pas un cône de dégâts ni un éclairage supplémentaire.</p><p class="small">Contrat courant : '+e(C['contract'])+'. Rejouer tous les anciens trajets et la ligne ordonnée. Aucune certification de GPU, téléphone physique, manette ou campagne native.</p>'
js='''<script>const f=document.querySelector('#filter');f.oninput=()=>{let n=0;for(const r of document.querySelectorAll('.room')){const show=r.dataset.search.includes(f.value.toLowerCase());r.classList.toggle('hide',!show);if(show)n++;}document.querySelector('#filter-note').textContent=n+' lieux affichés';};</script>'''
(R/'CODEX_LEVEL_DESIGN_V113.html').write_text(page('Aliens V113 — Codex Tenir les angles',body,js));(R/'CODEX_LEVEL_DESIGN_V113.md').write_text('\n\n'.join(md)+'\n')
selection=[('54_poste_rejoint.png','Hicks rejoint le poste désigné'),('55_secteurs_operations.png','Deux secteurs engagés dans Operations'),('56_newt_au_poste.png','Un appui pour Newt, sans arme'),('57_rotation_affut.png','Rotation locale de l’affût'),('58_axe_occupe.png','Un allié devant l’axe retient le tir'),('59_axe_degage.png','Dégager l’axe libère la sentinelle'),('60_defense_positions.png','La ligne ordonnée a tenu'),('61_tactique_paysage.png','Commandes hors terrain en paysage court'),('62_tactique_portrait.png','Même état en portrait'),('63_repli_angles.png','Retour avec l’équipe et ses ressources réelles')]
by={c['file']:c for c in B['captures']}
def picture(file,title):
 c=by[file];raw=(R/'report/captures-v113'/file).read_bytes();assert raw.startswith(b'\x89PNG\r\n\x1a\n');return f'<figure><h3>{e(title)}</h3><img loading="lazy" src="data:image/png;base64,{base64.b64encode(raw).decode()}" alt="{e(title)} — capture directe du jeu V113"><figcaption>{e(c["origin"])}. <strong>{e(file)}</strong> : PNG direct Chromium non retouché, aucun concept généré ni reconstruction depuis des coordonnées.</figcaption></figure>'
body='<p class="kicker">ALIENS V113 / rapport de livraison</p><h1>Tenir les angles</h1><p class="lead">Donner une position ne suffit plus : le groupe doit la rejoindre et garder une ligne de tir sans se masquer mutuellement.</p>'+metrics([(node,'tests Node réussis'),(len(B['tests']),'contrôles navigateur'),(8,'opérations terminées'),(len(B['captures']),'captures directes')])
body+='<nav><a href="JOUER_ALIENS_V113.html">Jouer V113</a><a href="CODEX_LEVEL_DESIGN_V113.html">Codex</a><a href="#preuves">Vérifications</a><a href="#limites">Périmètre</a></nav><div class="callout">Suite réelle du ZIP V112 « Baliser le repli » fourni. Ces dix images sont embarquées byte-for-byte depuis le programme distribué exécuté dans Chromium. Les exports de parcours et les manipulations de l’interface sont distingués dans chaque légende.</div>'
body+='<h2>Des ordres liés au sol et aux silhouettes</h2><p>X choisit un poste visible, N engage un secteur de100°, 2 retient ou autorise le feu. Les membres choisis sont indépendants. Ils rejoignent leur appui par un chemin autour du mobilier et des autres acteurs ; aucune téléportation ne rattrape une route bouchée. Une réservation de groupe impossible est refusée entièrement. G/H/C quittent ce placement explicite, sans effacer la consigne de feu.</p><p>Newt recrutée peut rejoindre un poste, mais n’obtient aucun secteur ni munition. La sentinelle reste fixe : Ripley doit être à moins de76 unités pour tourner son affût pendant1,15s. Pause et reprise conservent l’avancement ; marche, tir, blessure ou cible devenue invalide annulent le geste. Les munitions ne changent pas en orientant.</p><h2>Les tirs automatiques attendent un axe libre</h2><p>Un allié vivant placé avant la première cible ou paroi retient le tir des Marines et de la sentinelle. Une silhouette derrière la première cible ne l’annule pas. Cette sécurité d’acquisition ne redéfinit pas les tirs manuels du joueur. Elle conserve la portée, l’angle, les munitions et la perception dans le noir. Les marquages de secteur sont abrégés visuellement à160 unités, sans ajouter une lumière ou un radar.</p>'
for f,t in selection:body+=picture(f,t)
body+='<h2 id="preuves">Recette exécutée sur le HTML distribué</h2>'+table(['Recette','Résultat','Portée'],[['Node',node,'486 tests historiques +93 nouveaux tests dirigés'],['Navigateur',len(B['tests']),'236 contrôles réexécutés +55 nouveaux'],['Parcours complets',8,'2 directs,2 logistiques,brèche,noir,balises,positions'],['Captures',len(B['captures']),'10 PNG intégrés sans modification']])
body+='<h3>Un huitième parcours depuis l’insertion normale</h3><p>Le pilote rejoint Operations, désigne deux postes, exporte pendant leur déplacement, reprend puis engage deux secteurs et des consignes de feu distinctes. Il rétablit le relais, recrute Newt, lui donne un poste réel puis la rappelle. À la ligne, il prépare l’affût, exporte pendant sa rotation et place les trois compagnons hors de l’axe. Il ouvre la porte, dégage la trajectoire et autorise la défense sans tir manuel avant de rallier le repli.</p><p>Le pilote lit les données pour choisir ses chemins et ses entrées. Il utilise les commandes publiques sans réécrire positions, vies, chargeurs, ressources ou objectifs. Ce n’est ni un joueur humain aveugle aux données ni une garantie de campagne native. Les fixtures dirigées sont comptées à part.</p>'
body+=table(['Entrées / sous-pas','Temps simulé','Munitions sentinelle finales','État final'],[[D['inputs'],f"{D['elapsed']:.3f} s",D['sentryAmmo'],'repli confirmé']]);body+=table(['Membre','PV','Munitions'],[[a['id'],a['hp'],a['ammo']]for a in D['team']])
mt=D['orders']['metrics'];body+=table(['Postes transmis','Arrivées physiques','Secteurs','Affûts orientés'],[[mt['postOrders'],mt['arrivals'],mt['sectorOrders'],mt['turnsCompleted']]])
body+='<p>Les secondes simulées ne représentent pas une durée humaine. Les réserves restent celles du parcours. Dans une recette navigateur distincte, Ripley bloque volontairement la ligne après l’ouverture : la sentinelle ne tire pas. Le déplacement de Ripley vers le bas libère l’axe et les cartouches sont alors consommées.</p><h3>Corrections pendant la recette</h3><p>Un poste pouvait rester bloqué après un contournement de compagnon : le chemin est maintenant recalculé depuis la position réellement atteinte. Les essais de contournement incluent des tangentes diagonales, sans supprimer d’obstacles. Des pilotes anciens plaçaient un allié directement devant la sentinelle ; leur attente de consommation était devenue incorrecte. Leurs trajets dégagent désormais l’axe par les commandes publiques avant d’attendre le feu, au lieu de supprimer la nouvelle sécurité.</p>'
body+='<h2 id="limites">Périmètre exact</h2><p>Branche autonome V112 poursuivie. Aucun raccord aux64 salles natives de Tantalus, aucun push ni déploiement, aucun nouveau final historique. Catalogue inchangé : dix inspections, neuf lieux d’opération, onze liaisons, treize contacts, une sentinelle et cinq objectifs locaux.</p><p>Graphismes procéduraux stylisés, pas de nouveaux sprites de production. Pas de nouvelles salles, arme, couvert destructible, tir de suppression, changement de moral, véhicule déplacé ou formation traversant les portes d’un bloc. Les transferts restent discrets et les tirs locaux. La sentinelle tourne mais ne se transporte pas. La sécurité automatique n’est pas une nouvelle balistique des tirs du joueur.</p><p>Les commandes et le HUD restent hors terrain. Les viewports844×390 et390×844 sont émulés, pas des téléphones physiques. Le terrain reste petit en écran court. Les tests réels de transport file://, la distribution et l’intégrité sont consignés séparément.</p><h2>Provenance</h2>'
body+='<p class="small">Source V112 ZIP : c9c13930b5451af046a6e9d7a3e69bf90cc0fa2f42b0ed336b01be9d236f7c06<br>HTML V113 : '+B['htmlSha256']+'<br>Contrat : '+C['contract']+'</p>'
(R/'RAPPORT_ILLUSTRE_V113.html').write_text(page('Aliens V113 — Rapport illustré Tenir les angles',body));(R/'report/report-selection-v113.json').write_text(json.dumps({'captured':len(B['captures']),'embedded':len(selection),'rules':len(rules),'files':[x[0] for x in selection],'rawImageBytesUnchanged':True},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'codexRooms':len(C['rooms']),'rules':len(rules),'embedded':len(selection),'captures':len(B['captures'])}))
